"""Immutable optimization-before PR #6 source, verified by cumulative patch hash."""
import hashlib
import subprocess
from prepare_bridge import COMMIT, ROOT

SOURCE_COMMIT = '086ab720b3c43ebe4ba8ac7545e34c0c9bc41aad'
PATCH_SHA = '5651320c322ac731295e83cae5537a4ce3c4207362da88cbd730dfcf3c07520b'


def prepare():
    directory = ROOT / '.deps/ipc-pr6-before'
    patch_file = ROOT / '.deps/ipc-pr6-before.patch'
    if patch_file.exists():
        patch = patch_file.read_bytes()
    else:
        # CI has full history. A local checkout imported through the connector
        # can have different Git commit IDs; accept only identical patch bytes.
        candidates = [SOURCE_COMMIT] + subprocess.check_output(
            ['git', 'rev-list', '--all', '--', 'patches/l4d2-bridge.patch'], cwd=ROOT,
            text=True).splitlines()
        patch = None
        for commit in candidates:
            result = subprocess.run(['git', 'show', commit + ':patches/l4d2-bridge.patch'],
                                    cwd=ROOT, capture_output=True)
            if result.returncode == 0 and hashlib.sha256(result.stdout).hexdigest() == PATCH_SHA:
                patch = result.stdout
                break
        if patch is None:
            raise RuntimeError('Immutable pre-optimization PR #6 patch not found')
        patch_file.write_bytes(patch)
    if hashlib.sha256(patch).hexdigest() != PATCH_SHA:
        raise RuntimeError('Pre-optimization PR #6 patch hash mismatch')
    source = ROOT / '.deps/dxvk-remix'
    if not directory.exists():
        subprocess.run(['git', 'worktree', 'add', '--detach', str(directory), COMMIT],
                       cwd=source, check=True)
        subprocess.run(['git', 'apply', '--check', '-'], input=patch, cwd=directory, check=True)
        subprocess.run(['git', 'apply', '-'], input=patch, cwd=directory, check=True)
    else:
        subprocess.run(['git', 'apply', '--reverse', '--check', '-'],
                       input=patch, cwd=directory, check=True)
    return directory


if __name__ == '__main__':
    print(prepare())
